mapper.select:
SELECT * FROM exam_application
WHERE patient_id = #{patientId}
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE exam_application
SET status = #{status}
WHERE id = #{id}

UPDATE exam_application
SET status = #{status},
    exec_time = NOW(),
    exec_operator_id = #{execOperatorId}
WHERE id = #{id}

mapper.select:
SELECT * FROM exam_application
WHERE status = #{status}
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE exam_application
SET pay_status = #{payStatus},
    total_amount = #{amount}
WHERE id = #{id}

mapper.select:
SELECT * FROM exam_application
WHERE status = #{status}
  AND item_type <> 'LAB'
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT * FROM exam_application
WHERE status = #{status}
  AND item_type = 'LAB'
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE exam_application
SET pay_status = 'REFUNDED'
WHERE id = #{id}
